import React from "react";
import Sidebar from "./Sidebar";

export default function CustomerDashboard({ onLogout }) {
  const [active, setActive] = React.useState("dashboard");
  const [searchQuery, setSearchQuery] = React.useState("");
  const [showSearchForm, setShowSearchForm] = React.useState(false);
  const [searchFilters, setSearchFilters] = React.useState({
    name: "",
    location: "",
    city: "",
    pincode: "",
    area: "",
  });
  const searchPanelRef = React.useRef(null);

  React.useEffect(() => {
    const handleClickOutside = (event) => {
      if (showSearchForm && searchPanelRef.current && !searchPanelRef.current.contains(event.target)) {
        setShowSearchForm(false);
      }
    };

    document.addEventListener("mousedown", handleClickOutside);
    document.addEventListener("touchstart", handleClickOutside);

    return () => {
      document.removeEventListener("mousedown", handleClickOutside);
      document.removeEventListener("touchstart", handleClickOutside);
    };
  }, [showSearchForm]);


  const handleSearchStart = () => {
    if (!showSearchForm) {
      setShowSearchForm(true);
      return;
    }

    if (searchQuery.trim()) {
      setShowSearchForm(true);
    }
  };

  const handleSearchHover = () => {
    setShowSearchForm(true);
  };

  const handleSearchMouseLeave = () => {
    setShowSearchForm(false);
  };

  const handleSearchKeyDown = (event) => {
    if (event.key === "Enter") {
      event.preventDefault();
      handleSearchStart();
    }
  };

  const handleFilterChange = (field, value) => {
    setSearchFilters((prev) => ({ ...prev, [field]: value }));
  };

  const dashboardOffers = [
    {
      tag: "Bike Offer",
      title: "Flash Bike Savings",
      subtitle: "Save 20% on premium bike rentals this week.",
      detail: "Highlight your bike fleet with a fast booking boost and extra visibility.",
    },
    {
      tag: "Car Offer",
      title: "Weekend Car Special",
      subtitle: "Extra cashback on weekend car bookings.",
      detail: "Showcase your best car deals for short trips and road trips alike.",
    },
    {
      tag: "SUV Offer",
      title: "Family SUV Promo",
      subtitle: "Get more family group bookings with special SUV pricing.",
      detail: "Promote comfort and space for longer journeys with this offer.",
    },
  ];

  const [offerIndex, setOfferIndex] = React.useState(0);

  const handlePrevOffer = () => {
    setOfferIndex((prev) => (prev - 1 + dashboardOffers.length) % dashboardOffers.length);
  };

  const handleNextOffer = () => {
    setOfferIndex((prev) => (prev + 1) % dashboardOffers.length);
  };

  const chartMetrics = [
    { title: "Total Vehicles", value: "128", detail: "All active listings", progress: 82 },
    { title: "Weekly Bookings", value: "86", detail: "Confirmed rides this week", progress: 66 },
    { title: "Avg. Rating", value: "4.8", detail: "Customer feedback score", progress: 95 },
    { title: "Top City", value: "Bangalore", detail: "Most searched location", progress: 78 },
    { title: "Available Bikes", value: "42", detail: "Ready for immediate rent", progress: 88 },
    { title: "Available Cars", value: "31", detail: "Popular city vehicles", progress: 74 },
    { title: "Available SUVs", value: "22", detail: "Comfort and space", progress: 69 },
    { title: "Available Buses", value: "8", detail: "Group travel options", progress: 52 },
    { title: "New Customers", value: "112", detail: "Joined this month", progress: 83 },
    { title: "Searches Today", value: "340", detail: "Recent vehicle searches", progress: 90 },
    { title: "Top Area", value: "Indiranagar", detail: "Most requested area", progress: 77 },
    { title: "Express Trips", value: "19", detail: "Same-day bookings", progress: 60 },
    { title: "Most Viewed", value: "Honda Activa", detail: "Highest page views", progress: 94 },
    { title: "Most Booked", value: "Maruti Swift", detail: "Top rented vehicle", progress: 89 },
    { title: "Top SUV", value: "Tata Nexon", detail: "Preferred family SUV", progress: 72 },
    { title: "Peak Demand", value: "Weekend", detail: "Highest booking window", progress: 82 },
  ];

  const SearchPanel = ({ fullWidth = true }) => (
    <div style={fullWidth ? { ...styles.panel, gridColumn: "1 / -1" } : styles.panel}>
      <div style={styles.panelHeader}>
        <div>
          <h2 style={styles.panelTitle}>Search Vehicles</h2>
          <p style={styles.panelText}>Enter a keyword to open the advanced search form below.</p>
        </div>
      </div>
      <div
        ref={searchPanelRef}
        style={styles.searchWrapper}
        onMouseEnter={handleSearchHover}
        onMouseLeave={handleSearchMouseLeave}
      >
        <div style={styles.searchRowSimple}>
          <input
            style={styles.searchInput}
            placeholder="Search vehicles..."
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
            onKeyDown={handleSearchKeyDown}
            onFocus={handleSearchHover}
          />
          <button
            type="button"
            style={styles.searchButton}
            onClick={handleSearchStart}
          >
            Search
          </button>
        </div>

        {showSearchForm && (
          <div style={styles.advancedForm}>
            <div style={styles.formHeader}>
              <h3 style={styles.formTitle}>Refine your search</h3>
              <p style={styles.formText}>Use one or more filters below to search by name, location, city, pincode, or area.</p>
            </div>
            <div style={styles.formGrid}>
              <div style={styles.formField}>
                <label style={styles.formLabel}>Vehicle Name</label>
                <input
                  style={styles.formInput}
                  value={searchFilters.name}
                  onChange={(e) => handleFilterChange("name", e.target.value)}
                  placeholder="e.g. Honda Activa"
                />
              </div>
              <div style={styles.formField}>
                <label style={styles.formLabel}>Location</label>
                <input
                  style={styles.formInput}
                  value={searchFilters.location}
                  onChange={(e) => handleFilterChange("location", e.target.value)}
                  placeholder="e.g. MG Road"
                />
              </div>
              <div style={styles.formField}>
                <label style={styles.formLabel}>City</label>
                <input
                  style={styles.formInput}
                  value={searchFilters.city}
                  onChange={(e) => handleFilterChange("city", e.target.value)}
                  placeholder="e.g. Bangalore"
                />
              </div>
              <div style={styles.formField}>
                <label style={styles.formLabel}>Pincode</label>
                <input
                  style={styles.formInput}
                  value={searchFilters.pincode}
                  onChange={(e) => handleFilterChange("pincode", e.target.value)}
                  placeholder="e.g. 560001"
                />
              </div>
              <div style={styles.formField}>
                <label style={styles.formLabel}>Area</label>
                <input
                  style={styles.formInput}
                  value={searchFilters.area}
                  onChange={(e) => handleFilterChange("area", e.target.value)}
                  placeholder="e.g. Indiranagar"
                />
              </div>
            </div>
            <div style={styles.formActions}>
              <button style={styles.searchButton} onClick={() => setShowSearchForm(true)}>
                Apply Filters
              </button>
            </div>
          </div>
        )}
      </div>
    </div>
  );

  return (
    <div style={{ display: "flex" }}>
      <Sidebar active={active} onSelect={(k) => setActive(k)} />
      <div style={styles.page}>
        <header style={styles.header}>
          <div style={styles.brand}>
            <div style={styles.logo}>VehicleHub</div>
            <div style={styles.tagline}>Ride Anytime, Anywhere</div>
          </div>
          <div style={styles.userPanel}>
            <div style={styles.userAvatar}>RK</div>
            <div>
              <div style={styles.userName}>Rahul Kumar</div>
              <div style={styles.userRole}>Customer</div>
            </div>
            <button style={styles.logoutButton} onClick={onLogout}>Logout</button>
          </div>
        </header>


        <main style={styles.mainGrid}>
              <SearchPanel />

          <section style={{ ...styles.panel, ...styles.fullWidthSection, ...styles.dashboardOfferSection }}>
            <div style={styles.offerHeader}>
              <div>
                <h3 style={styles.panelTitle}>Today's Offers</h3>
                <p style={styles.panelText}>Automatic owner-only offers for bike, car, SUV and truck rentals.</p>
              </div>
            </div>
            <div style={styles.offersCarousel}>
              <button type="button" style={styles.carouselArrow} onClick={handlePrevOffer}>
                &lt;
              </button>
              <div style={styles.offerSlide}>
                <span style={styles.offerChip}>{dashboardOffers[offerIndex].tag}</span>
                <h4 style={styles.offerTitle}>{dashboardOffers[offerIndex].title}</h4>
                <p style={styles.offerSubtitle}>{dashboardOffers[offerIndex].subtitle}</p>
                <p style={styles.offerDetail}>{dashboardOffers[offerIndex].detail}</p>
                <div style={styles.offerMeta}>
                  <span>{offerIndex + 1} of {dashboardOffers.length}</span>
                </div>
              </div>
              <button type="button" style={styles.carouselArrow} onClick={handleNextOffer}>
                &gt;
              </button>
            </div>
          </section>

          <section style={{ ...styles.panel, ...styles.fullWidthSection, ...styles.chartsSection }}>
            <div style={styles.offerHeader}>
              <div>
                <h3 style={styles.panelTitle}>Popular Vehicles Charts</h3>
                <p style={styles.panelText}>A quick analytics view of fleet performance and demand.</p>
              </div>
            </div>
            <div style={styles.chartGrid}>
              {chartMetrics.map((metric) => (
                <div key={metric.title} style={styles.chartCard}>
                  <div style={styles.chartCardHeader}>
                    <span style={styles.chartValue}>{metric.value}</span>
                    <span style={styles.chartLabel}>{metric.title}</span>
                  </div>
                  <div style={styles.chartBarWrapper}>
                    <div
                      style={{
                        ...styles.chartBar,
                        width: `${metric.progress}%`,
                      }}
                    />
                  </div>
                  <p style={styles.chartDetail}>{metric.detail}</p>
                </div>
              ))}
            </div>
          </section>
        </main>
      </div>
    </div>
  );
}

const styles = {
